/* A track project: the source of a track, a folder such as <workspace>/tracks/<id>/ (notes/dep59-track-editor-design.md §4.1).
 *
 *   project.ini   id, name, author, stem, art (the stage's FAM, relative to the project folder), redistributable, edge (the verge's material)
 *   trace.json    the centre line: its control points (x, z in units) and the road width byte of its nodes
 *
 * The folder's build/ is regenerated by the editor (build.h); the editor writes nothing else in it. */
#ifndef TNFS_TRACK_EDITOR_PROJECT_H
#define TNFS_TRACK_EDITOR_PROJECT_H

#include "formats/mod_ini.h"
#include "formats/track_trace.h"

#include <stddef.h>

enum {
    PROJECT_TEXT_MAX = 128,
    PROJECT_POINTS_MAX = 2400,    /* a road of 599 segments has about this many control points at most; more are refused on load */
    PROJECT_START_GAP = 100,      /* a new project's straight (project_start_points) has a control point every this many metres at most */
    PROJECT_PATH_MAX = 512,
    PROJECT_WIDTH_MIN = 8,        /* track_gen's layout range for a road's width (the road width byte) */
    PROJECT_WIDTH_MAX = 120
};

/* A new project is a straight as long as the shortest stage the game races (track_trace_stage_min_length, about 1.3 km), so it is born with nothing red:
 * this many control points, evenly spaced, no more than PROJECT_START_GAP metres apart. */
int project_start_points(void);

typedef struct {
    char id[MOD_INI_ID_MAX + 1];
    char name[PROJECT_TEXT_MAX];
    char author[PROJECT_TEXT_MAX];
    char stem[9];                 /* the piece's stem: 1..7 of A-Z 0-9, not AL, CL, CY or TR first */
    char art[PROJECT_PATH_MAX];   /* the stage's art, a FAM file: relative to the project folder, or absolute; "" is refused by the build */
    int redistributable;          /* the author's word on the art's licence (the editor writes no CD byte) */
    char edge[8];                 /* the verge's material, one of PROJECT_EDGES: what the engine makes of the ground off the road (mod.ini's edge=) */
} Project;

/* the engine's six verge words, in its order (core/formats/track_piece.c): project.ini's edge= is one of them, grass when it is not there */
extern const char *const PROJECT_EDGES[];

enum { PROJECT_TRACE_VERSION = 5 };   /* trace.json's newest version: 1 had the points and the width; 2 adds the road keys; 3 the keys' values past the width (the
                                       * shoulder surfaces of step 2b, the road's sides of step 3). A file of a newer version is refused. The writer writes the lowest
                                       * that holds what the trace has (2, or 3 with such a value).
                                       * 4: the fence step's (fence_height, fence_art, barrier_*_custom); a file before it reads its barrier keys as Custom from point 0
                                       * 5: heights, the points as [x, z, h] (dep95); a file with no height is still written as before */

typedef struct {
    TracePoint *points;           /* malloc'd, `count` of them */
    int count;
    double width;                 /* the road width byte at the start, as track_gen takes it: the project's width, which a road key on a point changes from there on */
    TraceKey *keys;               /* the road keys, ascending by point: malloc'd, `key_count` of them (NULL with none), room for `key_cap` */
    int key_count, key_cap;
} Trace;

/* The road's width as the author sees it: the tarmac edge to edge in metres. The byte is the distance of each edge from the centre in 1/8 m, so the
 * width is byte / 4 (the template's 40 is 10 m; 8..120 is 2..30 m). */
double project_road_metres(double width_byte);
double project_width_from_road(double metres);
extern const char *const PROJECT_ROAD_TIP;

/* Reads the project in `dir` (its project.ini and trace.json). 1 with `out` and `trace` filled (the caller frees trace->points and trace->keys); 0 with
 * `why` (a sentence naming the file) otherwise. */
int project_open(const char *dir, Project *out, Trace *trace, char *why, size_t why_cap);

/* Creates the files of a new project in `dir` where they are missing: project.ini with `id`, and trace.json as a straight. Existing files are
 * kept. `generic_art` is the editor's own GENERIC.FAM (art.h), or NULL when there is none: a new project gets a copy of it as GENERIC.FAM and
 * art=GENERIC.FAM; a project of the first Studio, whose art= points at ../generic-straight/GENERIC.FAM (a path only the source tree had) and
 * is not readable, gets the copy and the line rewritten. Any other art= is left as it is. 1 on success, 0 with `why`. */
int project_create(const char *dir, const char *id, const char *generic_art, char *why, size_t why_cap);

/* The art of a project that kept the GENERIC.FAM of an older Studio (project_create copies it once): when the project's art= is GENERIC.FAM and that copy
 * is byte for byte one of `old` (SHA-256 in hex, NULL-ended: PROJECT_OLD_ARTS), it is replaced by `generic`, the one Studio carries now, and the note says so.
 * A copy that is neither the current one nor a known old one (the author edited it) is left alone and the note says that; an art= of another name is
 * not looked at. 1 when it was replaced, else 0; `note` is "" when there is nothing to say. */
extern const char *const PROJECT_OLD_ARTS[];
int project_art_refresh(const char *dir, const char *generic, const char *const old[], char *note, size_t note_cap);
/* 1 when the project at `dir` draws with Studio's current generic art: art=GENERIC.FAM and that copy byte for byte `generic`. A tarmac shoulder (a road key)
 * draws with that art's asphalt bank (TRACK_GENERIC_SLOT_TARMAC); an art of the author's own may have anything there, and Problems says so */
int project_art_is_generic(const char *dir, const char *generic);

/* Sets the edge= line of `dir`'s project.ini to `edge` (one of PROJECT_EDGES): the line is replaced where it is or added at the end, every other
 * byte of the file stays. 1 on success, 0 with `why` (an unknown word leaves the file as it is). */
int project_set_edge(const char *dir, const char *edge, char *why, size_t why_cap);

/* Writes trace.json of `dir` (through a temporary file, then renamed): the points and the project's width, and a "keys" array only when there are keys:
 * {"point": 3, "width_m": 14.0, "shoulder_l_surface": "tarmac"}. Version 3 when a key sets a shoulder surface (a Studio that reads only 2 refuses it instead of
 * losing the surfaces on saving), else 2. 1 on success, 0 with `why`. */
int project_save_trace(const char *dir, const Trace *trace, char *why, size_t why_cap);

#endif
